"""Reconstruct July 2023 sales from warehouse dispatches."""

import csv
import json
from decimal import Decimal
from pathlib import Path


def answer() -> int:
    dataset = Path('/app/dataset')
    with (dataset / 'product_catalog.csv').open(newline='') as f:
        prices = {
            row['product_id']: Decimal(row['unit_price'].replace(',', '.'))
            for row in csv.DictReader(f)
        }

    # These eight dispatches form the exceptional batch at 03:17 on July 18.
    # The surrounding 02:00 and 04:00 sensor readings show meat at
    # 15.97/16.26 C (limit 4 C) and frozen goods at -3.13/-2.64 C
    # (limit -10 C). This is the clear spoilage disposal event.
    disposal_ids = {127, 128, 129, 130, 131, 132, 133, 134}
    revenue = Decimal('0')
    with (dataset / 'warehouse_dispatches.csv').open(newline='') as f:
        for row in csv.DictReader(f):
            if not '2023-07-01' <= row['timestamp'] < '2023-08-01':
                continue
            if int(row['dispatch_id']) in disposal_ids:
                continue
            # Separate dispatch IDs remain separate, even if details match.
            revenue += int(row['quantity']) * prices[row['product_id']]

    # All dispatches: PLN 50,891; confirmed disposals: PLN 10,000.
    assert revenue == revenue.to_integral_value()
    return int(revenue)


if __name__ == '__main__':
    with open('/app/answer.json', 'w') as f:
        json.dump(answer(), f, default=list)
